public sealed class SearchPage(IPage page)
{
    private readonly ILocator _input = page.Locator("[aria-label='Enter your search term']");

    public Task GotoAsync() => page.GotoAsync("https://bing.com");

    public async Task SearchAsync(string text)
    {
        await _input.FillAsync(text);
        await _input.PressAsync("Enter");
    }
}

