public sealed class LoginPage : LoadableComponent<LoginPage>
{
    private readonly IWebDriver _driver;
    public LoginPage(IWebDriver driver) => _driver = driver;

    protected override void ExecuteLoad() => _driver.Navigate().GoToUrl("https://app/login");
    protected override bool EvaluateLoadedStatus() => _driver.FindElements(By.Id("user")).Count > 0;

    public HomePage LoginAs(string u, string p)
    {
        _driver.FindElement(By.Id("user")).SendKeys(u);
        return new HomePage(_driver);
    }
}
